<template><a-card v-if="canRead"><a-button v-if="canWrite">Create</a-button><a-table :data-source="table.items.value" :pagination="false"><template #bodyCell="{column,record}"><template v-if="column.key==='actions'"><a v-if="canWrite">Edit</a><a-popconfirm v-if="canDelete" @confirm="remove(record)"><a>Delete</a></a-popconfirm></template></template></a-table></a-card></template>
<script setup lang="ts">
import{computed,inject,onMounted}from'vue';import{usePermission}from'@/hooks/usePermission';import{useTable}from'@/hooks/useTable';import type{ObservabilityDashboardApi}from'@/api/observability/dashboard';import type{Dashboard}from'@/types/observability';const api=inject<ObservabilityDashboardApi>('observabilityDashboardApi')!;const p=usePermission();const canRead=computed(()=>p.has('observability:dashboard:read')),canWrite=computed(()=>p.has('observability:dashboard:write')),canDelete=computed(()=>p.has('observability:dashboard:delete'));const table=useTable<Dashboard,{}>({fetcher:async({page,pageSize})=>{const x=await api.list({page,page_size:pageSize});return{items:x.items,total:x.total}}});async function remove(row:Dashboard){await api.remove(row.id);await table.reload()}onMounted(()=>void table.reload());defineExpose({canRead,canWrite,canDelete,remove})
</script>
